"""Emitter protocol + shared types.

An Emitter consumes a HarnessIR and writes a target-specific output tree. v1 ships
`claude_code`; v2 will add `codex`, `copilot`, `gemini`, `cursor` per plan §3.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from pathlib import Path
from typing import TYPE_CHECKING, Protocol

from harness.ir.model import HarnessIR
from harness.pipeline.writer import WriteResult

if TYPE_CHECKING:
    from harness.config.models import HarnessConfig


@dataclass
class EmitOptions:
    out_dir: Path
    dry_run: bool = False
    diff: bool = False
    legacy_commands: bool = False  # also emit .claude/commands/<name>.md alongside skills
    config: HarnessConfig | None = None  # full config for domain-aware emission


@dataclass
class EmitResult:
    write: WriteResult = field(default_factory=WriteResult)
    warnings: list[str] = field(default_factory=list)


class Emitter(Protocol):
    target: str

    def emit(self, ir: HarnessIR, opts: EmitOptions) -> EmitResult: ...

    def supported_features(self) -> set[str]: ...
